"""
Copies the Question Paper Generator's core logic from the Streamlit
app (app.py in the Question-Paper-Generator repo) into core/qpg_core.py,
so this service and the Streamlit app always run the same code.

Usage:
    python sync_core.py /path/to/Question-Paper-Generator/app.py

Everything above the "# APP UI" marker is copied verbatim; the only
change is `import streamlit as st` -> `import st_shim as st`.
"""

import pathlib
import sys

MARKER = "\n# APP UI\n"
HEADER = (
    "# AUTO-GENERATED by sync_core.py from the Question Paper Generator\n"
    "# Streamlit app (app.py). Do not edit by hand — fix app.py and re-sync.\n"
)


def main():
    if len(sys.argv) != 2:
        sys.exit(__doc__)

    source = pathlib.Path(sys.argv[1]).read_text(encoding="utf-8")
    cut = source.find(MARKER)

    if cut < 0:
        sys.exit("Couldn't find the '# APP UI' marker in app.py.")

    core = source[:cut].rstrip() + "\n"

    if core.count("import streamlit as st\n") != 1:
        sys.exit("Expected exactly one 'import streamlit as st' line.")

    core = core.replace("import streamlit as st\n", "import st_shim as st\n")
    target = pathlib.Path(__file__).parent / "core" / "qpg_core.py"
    target.write_text(HEADER + core, encoding="utf-8")
    print(f"Wrote {target} ({core.count(chr(10))} lines)")


if __name__ == "__main__":
    main()
